{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Guided Intensives & Short Supports</title>
  <meta name="description" content="Short, focused clinical sessions and guided practices to move through specific moments. Confidential, pragmatic, and attuned to real life.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <svg class="site-pattern" aria-hidden="true">
    <use href="assets/img/pattern.svg#pattern" />
  </svg>
  <header class="site-header">
    <div class="container">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <button class="nav-toggle" aria-expanded="false" aria-controls="nav-list">Menu</button>
        <ul id="nav-list">
          <li><a href="index.html">Home</a></li>
          <li><a href="about.html">Why Work Together</a></li>
          <li><a href="specialties.html">Areas I See</a></li>
          <li><a href="approach.html">How I Work</a></li>
          <li><a href="fees.html">Investment</a></li>
          <li><a href="faq.html">Questions</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Connect</a></li>
        </ul>
      </nav>
      <a class="cta primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal" id="hero">
      <div class="container">
        <h1>Short intensives and practical tools for clear next steps</h1>
        <p class="lead">I offer focused sessions and guided self-practices to help you move through a specific concern — efficient, confidential, and clinically informed.</p>
        <div class="hero-actions">
          <a class="btn" href="book.html">Reserve an Intensive</a>
          <button class="btn ghost" id="try-exercise">Try a Quick Exercise</button>
        </div>
        <p class="meta">Sessions are clinical and confidential. If you are in crisis, please call local emergency services or a crisis line — I do not provide emergency care here.</p>
      </div>
    </section>

    <!-- Social proof -->
    <section class="social-proof reveal" id="social-proof">
      <div class="container narrow">
        <h2>What people notice after a focused visit</h2>
        <ul class="testimonials">
          <li>"A shorter, clearer way to get momentum when I felt stuck." — client</li>
          <li>"Practical steps I could try between sessions." — client</li>
          <li>"A calm space to sort priorities without hours of processing." — client</li>
        </ul>
      </div>
    </section>

    <!-- Benefits (order different) -->
    <section class="benefits reveal" id="benefits">
      <div class="container">
        <h2>How an intensive can help</h2>
        <div class="grid">
          <div class="card">
            <h3>Clarity</h3>
            <p>We focus on one pressing question and create immediate next steps you can try.</p>
          </div>
          <div class="card">
            <h3>Short & Strategic</h3>
            <p>Work that fits a tight schedule — single visits, half-day options, or a few-session arc.</p>
          </div>
          <div class="card">
            <h3>Practical Tools</h3>
            <p>Breathing, journaling prompts, and small experiments tailored to your life.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Process -->
    <section class="process reveal" id="process">
      <div class="container narrow">
        <h2>Typical short-form path</h2>
        <ol class="steps">
          <li>
            <strong>Brief Intake</strong>
            <p>We clarify the focus and set a target for the visit.</p>
          </li>
          <li>
            <strong>Focused Session</strong>
            <p>A time-limited, goal-oriented conversation with practical guidance.</p>
          </li>
          <li>
            <strong>Tools & Plan</strong>
            <p>Specific practices and suggestions you can test afterward.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- CTA block -->
    <section class="cta-block reveal" id="cta-block">
      <div class="container">
        <h2>Ready for a concentrated session?</h2>
        <p>Short intensives can be scheduled as a single meeting or a compact series. If you’re curious, start with a booking or try a short guided exercise right here.</p>
        <div class="actions">
          <a class="btn large" href="book.html">See Availability & Book</a>
          <a class="btn ghost" href="contact.html">Ask a Question</a>
        </div>
      </div>
    </section>

    <!-- FAQ excerpt -->
    <section class="faq-preview reveal" id="faq-preview">
      <div class="container narrow">
        <h2>Common questions</h2>
        <dl>
          <dt>What are intensives?</dt>
          <dd>Time-limited, clinically guided sessions focused on a specific concern rather than ongoing weekly therapy.</dd>
          <dt>Is this therapy?</dt>
          <dd>These are clinical services offered by a licensed clinician. They are not emergency services, and they are not a substitute for ongoing care when that’s needed.</dd>
        </dl>
        <p><a href="faq.html">See more questions & answers</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <div class="contact">
        <p>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</p>
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div class="legal">
        <p>Confidentiality: Sessions are held in confidence with normal clinical limits (e.g., risk of harm, as required by law). Scope: Services are focused, short-term supports and not a replacement for ongoing, intensive psychiatric treatment when it is needed. If you are facing an emergency, please call local emergency services or a crisis hotline.</p>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exercise-modal" class="modal" aria-hidden="true">
    <div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="exercise-title">
      <button class="modal-close" id="modal-close" aria-label="Close">×</button>
      <h3 id="exercise-title">Try a Quick Practice</h3>
      <p class="modal-sub">Choose a short guided exercise to pause and reorient. No data is recorded.</p>
      <div class="exercise-controls">
        <label>
          <input type="radio" name="exercise" value="breathing" checked> Breathing (2 minutes)
        </label>
        <label>
          <input type="radio" name="exercise" value="journaling"> Journaling (prompt)
        </label>
        <label>
          <input type="radio" name="exercise" value="intention"> Intention setting (1 minute)
        </label>
      </div>
      <div class="exercise-area" id="exercise-area">
        <!-- dynamic content injected -->
      </div>
      <div class="modal-actions">
        <button class="btn" id="start-exercise">Start</button>
        <button class="btn ghost" id="cancel-exercise">Cancel</button>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
