<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200" preserveAspectRatio="xMidYMid meet">
  <defs>
    <pattern id="grain" width="20" height="20" patternUnits="userSpaceOnUse">
      <rect width="20" height="20" fill="#f7f2eb" />
      <path d="M0 10 C5 8 15 12 20 10" stroke="#e6d9c9" stroke-width="1" fill="none"/>
    </pattern>
    <linearGradient id="g" x1="0" x2="1">
      <stop offset="0" stop-color="#fffefc" stop-opacity="0.6"/>
      <stop offset="1" stop-color="#efe6dc" stop-opacity="0.2"/>
    </linearGradient>
    <clipPath id="clip"><rect x="0" y="0" width="200" height="200" rx="40"/></clipPath>
  </defs>
  <rect width="200" height="200" fill="url(#grain)"/>
  <g clip-path="url(#clip)">
    <g transform="translate(-40,-20) rotate(12 100 100)">
      <path d="M60 40 q40 30 120 20 q-20 50 -80 60 q-60 -10 -40 -80" fill="#c9a66b" opacity="0.06"/>
      <path d="M20 120 q60 -40 140 -30 q-20 60 -90 80 q-60 -20 -50 -50" fill="#8a5a3b" opacity="0.04"/>
    </g>
  </g>
  <rect width="200" height="200" fill="url(#g)"/>
  <g id="pattern" opacity="0.9">
    <use href="#grain" />
  </g>
</svg>"} 
